begin;
select set_config('nr.c',gen_random_uuid()::text,true),set_config('nr.a',gen_random_uuid()::text,true),set_config('nr.o',gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,email,raw_user_meta_data) select current_setting('nr.'||x)::uuid,'authenticated','authenticated','rollback-'||gen_random_uuid()||'@example.invalid','{}'::jsonb from unnest(array['c','a','o']) x;
update public.nextrole_members set role='admin' where id=current_setting('nr.a')::uuid;
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',current_setting('nr.c'),'role','authenticated')::text,true);
select set_config('nr.p',public.nextrole_action('privacy_request','{"kind":"export","message":"Rollback privacy request to verify account isolation."}')->>'id',true);
select set_config('request.jwt.claims',json_build_object('sub',current_setting('nr.o'),'role','authenticated')::text,true);
do $$ begin if exists(select 1 from public.nextrole_privacy_requests where id=current_setting('nr.p')::uuid) then raise exception 'Cross-account request leak'; end if; end $$;
select set_config('request.jwt.claims',json_build_object('sub',current_setting('nr.a'),'role','authenticated')::text,true);
select public.nextrole_action('privacy_respond',jsonb_build_object('id',current_setting('nr.p'),'expected_revision',1,'status','resolved','response','Rollback-only request reviewed.'));
select public.nextrole_action('member_suspend',jsonb_build_object('id',current_setting('nr.c'),'suspended',true,'reason','Rollback contact accessibility verification'));
select set_config('request.jwt.claims',json_build_object('sub',current_setting('nr.c'),'role','authenticated')::text,true);
select public.nextrole_action('privacy_request','{"kind":"other","message":"Suspended accounts retain access to this contact channel."}');
do $$ begin if not exists(select 1 from public.nextrole_privacy_requests where id=current_setting('nr.p')::uuid and status='resolved') then raise exception 'Owner cannot see reply'; end if; end $$;
set local role anon;
do $$ begin begin perform public.nextrole_action('privacy_request','{}'); raise exception 'Anonymous mutation allowed'; exception when insufficient_privilege then null; end; end $$;
reset role;
rollback;
select 'PASS: private request/reply, owner isolation, suspended-user contact and anonymous-write denial; all fixtures rolled back.' as verification;
